create table public.academy_staff(user_id uuid primary key references auth.users(id), role text not null check(role in ('admin','teacher')));
alter table public.academy_staff enable row level security;
create policy own_staff on public.academy_staff for select to authenticated using(user_id=auth.uid());
create table public.teachers(id uuid primary key default gen_random_uuid(), name text not null unique, subjects text[] not null);
create table public.students(id uuid primary key default gen_random_uuid(), user_id uuid unique references auth.users(id), first_name text not null,last_name text not null,father_name text not null,national_id text unique not null check(national_id ~ '^[0-9]{10}$'), mobile text not null, birth_date date not null,home_phone text,address text not null,teacher_id uuid references public.teachers(id) not null,subject text not null,weekday int not null check(weekday between 0 and 6),class_time time not null,opening_credit int not null default 0 check(opening_credit>=0),opening_debt bigint not null default 0 check(opening_debt>=0),rules_accepted_at timestamptz,created_at timestamptz default now(),unique(teacher_id,weekday,class_time));
create table public.payments(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id) not null,terms int not null check(terms in (1,2)),amount bigint not null, reference text not null unique,created_at timestamptz default now(),check(amount=terms*2000000));
create table public.expenses(id uuid primary key default gen_random_uuid(),category text not null,description text not null,amount bigint not null check(amount>0),expense_date date not null default current_date);
create table public.sessions(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id) not null,starts_at timestamptz not null,status text not null default 'scheduled' check(status in ('scheduled','completed','absent','teacher_cancelled','excused')),makeup_for uuid unique references public.sessions(id),teacher_share bigint not null default 0,unique(student_id,starts_at));
create table public.absence_requests(id uuid primary key default gen_random_uuid(),session_id uuid unique references public.sessions(id) not null,student_id uuid references public.students(id) not null,created_at timestamptz default now(),status text not null default 'pending' check(status in ('pending','approved','rejected')));
create table public.notices(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),message text not null,created_at timestamptz default now());
create schema if not exists academy_private;
create function academy_private.is_admin() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.academy_staff where user_id=auth.uid() and role='admin')$$;
revoke all on schema academy_private from public; grant usage on schema academy_private to authenticated;
revoke all on function academy_private.is_admin() from public;grant execute on function academy_private.is_admin() to authenticated;
alter table public.teachers enable row level security;
create policy admin_all on public.teachers for all to authenticated using(academy_private.is_admin()) with check(academy_private.is_admin());
grant select,insert,update,delete on public.teachers to authenticated;
alter table public.students enable row level security;
create policy admin_all on public.students for all to authenticated using(academy_private.is_admin()) with check(academy_private.is_admin());
grant select,insert,update,delete on public.students to authenticated;
alter table public.payments enable row level security;
create policy admin_all on public.payments for all to authenticated using(academy_private.is_admin()) with check(academy_private.is_admin());
grant select,insert,update,delete on public.payments to authenticated;
alter table public.expenses enable row level security;
create policy admin_all on public.expenses for all to authenticated using(academy_private.is_admin()) with check(academy_private.is_admin());
grant select,insert,update,delete on public.expenses to authenticated;
alter table public.sessions enable row level security;
create policy admin_all on public.sessions for all to authenticated using(academy_private.is_admin()) with check(academy_private.is_admin());
grant select,insert,update,delete on public.sessions to authenticated;
alter table public.absence_requests enable row level security;
create policy admin_all on public.absence_requests for all to authenticated using(academy_private.is_admin()) with check(academy_private.is_admin());
grant select,insert,update,delete on public.absence_requests to authenticated;
alter table public.notices enable row level security;
create policy admin_all on public.notices for all to authenticated using(academy_private.is_admin()) with check(academy_private.is_admin());
grant select,insert,update,delete on public.notices to authenticated;
create policy student_self on public.students for select to authenticated using(user_id=auth.uid());
create policy teachers_read on public.teachers for select to authenticated using(true);
create policy student_read on public.payments for select to authenticated using(exists(select 1 from public.students s where s.id=student_id and s.user_id=auth.uid()));
create policy student_read on public.sessions for select to authenticated using(exists(select 1 from public.students s where s.id=student_id and s.user_id=auth.uid()));
create policy student_read on public.absence_requests for select to authenticated using(exists(select 1 from public.students s where s.id=student_id and s.user_id=auth.uid()));
create policy student_read on public.notices for select to authenticated using(exists(select 1 from public.students s where s.id=student_id and s.user_id=auth.uid()));
create function public.session_guard() returns trigger language plpgsql set search_path='' as $$declare credits int;debt bigint;begin
if TG_OP='UPDATE' and old.status<>'scheduled' then raise exception 'جلسه نهایی شده قابل تغییر نیست';end if;
if new.status in ('completed','absent') then
select s.opening_credit+coalesce((select sum(p.terms*4) from public.payments p where p.student_id=s.id),0)- (select count(*) from public.sessions c where c.student_id=s.id and c.status in ('completed','absent') and c.id<>new.id),s.opening_debt into credits,debt from public.students s where s.id=new.student_id for update;
if credits<=0 or debt>0 then raise exception 'شهریه پرداخت نشده؛ حضور مجاز نیست';end if;
end if;
new.teacher_share:=case when new.status='completed' then 300000 else 0 end;return new;end$$;
create trigger session_guard before insert or update on public.sessions for each row execute function public.session_guard();
create function public.absence_guard() returns trigger language plpgsql set search_path='' as $$declare start_time timestamptz;allowed int;used int;begin
select starts_at into start_time from public.sessions where id=new.session_id and student_id=new.student_id and status='scheduled';
if start_time is null or start_time<now()+interval '4 days' then raise exception 'اعلام غیبت حداقل ۴ روز قبل لازم است';end if;
select coalesce(sum(terms/2),0) into allowed from public.payments where student_id=new.student_id;
select count(*) into used from public.absence_requests where student_id=new.student_id and status<>'rejected' and id<>new.id;
if used>=allowed then raise exception 'سهمیه غیبت مجاز ندارید؛ هر پرداخت دو ترم یک سهمیه دارد';end if;return new;end$$;
create trigger absence_guard before insert on public.absence_requests for each row execute function public.absence_guard();
create policy student_request on public.absence_requests for insert to authenticated with check(status='pending' and exists(select 1 from public.students s where s.id=student_id and s.user_id=auth.uid()));
